MOD = 1000000007

def powerSumMod(n, k):
    d = k + 1  # the sum is a polynomial in n of degree d
    ys = [0]
    total = 0
    for x in range(1, d + 1):
        total = (total + pow(x, k, MOD)) % MOD
        ys.append(total)
    if n <= d:
        return ys[n]
    result = 0
    for i in range(d + 1):
        num, den = 1, 1
        for j in range(d + 1):
            if j != i:
                num = num * ((n - j) % MOD) % MOD
                den = den * ((i - j) % MOD) % MOD
        term = ys[i] * num % MOD * pow(den, MOD - 2, MOD) % MOD
        result = (result + term) % MOD
    return result
